import{z as o,x as l,o as t,c as d,q as A,j as r,D as e,d as B,s as n,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"信用组合的分散","description":"","frontmatter":{"title":"信用组合的分散","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bm2-credit-diversification.md","filePath":"quant/bm2-credit-diversification.md","lastUpdated":1791413859000}'),D={name:"quant/bm2-credit-diversification.md"};function p(C,E,c,F,m,u){const i=l("Mermaid");return t(),d("div",null,[E[2]||(E[2]=A('<h1 id="信用组合的分散" tabindex="-1">信用组合的分散 <a class="header-anchor" href="#信用组合的分散" aria-label="Permalink to &quot;信用组合的分散&quot;">​</a></h1><div class="epigraph"><p>信用收益的上界是利差，下界是违约。这种不对称使分散从品味变成算术：个券的跳跃必须摊薄，利差的贝塔则要明码持有。</p><footer>—— 据 Gupton, Finger and Bhatia, CreditMetrics 技术文档（1997）与 Fabozzi 相关章节整理</footer></div><p><a href="/quant/bm2-swaps-in-portfolio">上一课</a>解决了利率层的工具问题：久期可以在现券、期货与互换之间按成本调配。信用层的问题性质不同——它的坏消息是跳跃的，利差以基点计收，违约以面值计亏。本课写信用组合的分散：不是为了平均收益，而是把左尾摊薄到预算之内，并把摊不薄的那部分明码标价。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>信用组合的收益结构天生不对称：持有一只券最好的情形是收到全部利差与本金，最坏的情形是损失大半个面值。所以单券的违约风险——个券跳跃——无法靠定价补偿，只能靠分散摊薄；而全市场利差走动的系统性部分摊不薄，任何组合都满仓持有它。这就是信用分散的核心结构：可分散的用权重管理，不可分散的用对冲与预算管理。缺口在于「分散」常被当成名字数量：持仓 100 个发行人就自称分散，但相关性、行业重叠与权重倾斜可以让有效分散只剩一半——分散需要一个可度量的定义，而不是一张持仓清单的直觉。</p><p><span class="marginnote">直觉类比：个券违约像单个员工临时请假——雇够多的人总有替补，影响被摊平；系统性利差走阔像全行业同时罢工——雇再多员工也躲不掉。分散管理的是前者，后者只能靠对冲与预算，两者的工具箱不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>度量先行。集中度用有效 \\(N\\)：按权重算赫芬达尔指数，\\(N_{\\text{eff}} = 1/\\text{HHI}\\)，这是组合粒度的单一读数。约束分层：发行人上限、行业上限、评级桶与久期桶各给带宽，落在 <a href="/quant/bm2-bond-indexing">指数化一课</a> 同样的格子里，只是格子内换成损失分布的语言。期望损失 \\(EL = \\sum_i w_i \\cdot PD_i \\cdot LGD_i\\) 与相关无关，分散不改变它；非期望损失——损失分布的标准差与尾部——随违约相关上升，这才是分散真正要压的对象。据此分层配置：系统性利差贝塔用 CDS 指数承载或对冲（<a href="/quant/rc-cds-index-basis">CDS 指数与基差</a> 的口径），个券层只留有定价优势的名字赚分散后的溢价。压力必须含相关趋一的场景，因为那是分散失效的定义时刻。</p>',8)),(t(),r(s,null,{default:e(()=>[n(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E4%BF%A1%E7%94%A8%E7%BB%84%E5%90%88%E7%9A%84%E6%8D%9F%E5%A4%B1%E5%88%86%E5%B8%83%22%5D%20--%3E%20EL%5B%22%E6%9C%9F%E6%9C%9B%E6%8D%9F%E5%A4%B1%EF%BC%9A%E6%9D%83%E9%87%8D%E4%B9%98%20PD%20%E4%B9%98%20LGD%EF%BC%8C%E4%B8%8E%E7%9B%B8%E5%85%B3%E6%97%A0%E5%85%B3%22%5D%0A%20%20U%20--%3E%20UL%5B%22%E9%9D%9E%E6%9C%9F%E6%9C%9B%E6%8D%9F%E5%A4%B1%EF%BC%9A%E9%9A%8F%E8%BF%9D%E7%BA%A6%E7%9B%B8%E5%85%B3%E4%B8%8A%E5%8D%87%22%5D%0A%20%20CAP%5B%22%E7%BA%A6%E6%9D%9F%EF%BC%9A%E5%8F%91%E8%A1%8C%E4%BA%BA%E3%80%81%E8%A1%8C%E4%B8%9A%E3%80%81%E8%AF%84%E7%BA%A7%E6%A1%B6%22%5D%20--%3E%20GR%5B%22%E7%B2%92%E5%BA%A6%EF%BC%9A%E6%9C%89%E6%95%88%20N%20%E6%8C%89%20HHI%20%E8%AE%A1%22%5D%0A%20%20GR%20--%3E%20SYS%5B%22%E7%B3%BB%E7%BB%9F%E5%B1%82%EF%BC%9A%E6%8C%87%E6%95%B0%E6%89%BF%E8%BD%BD%E6%88%96%E5%AF%B9%E5%86%B2%E5%88%A9%E5%B7%AE%E8%B4%9D%E5%A1%94%22%5D%0A%20%20GR%20--%3E%20IDI%5B%22%E4%B8%AA%E5%88%B8%E5%B1%82%EF%BC%9A%E8%B5%9A%E5%88%86%E6%95%A3%E5%90%8E%E7%9A%84%E5%88%A9%E5%B7%AE%E6%BA%A2%E4%BB%B7%22%5D%0A%20%20SYS%20--%3E%20BS%5B%22%E5%9F%BA%E5%B7%AE%EF%BC%9A%E6%8C%87%E6%95%B0%E6%88%90%E5%88%86%E4%B8%8E%E6%8C%81%E4%BB%93%E4%B8%8D%E4%B8%80%E8%87%B4%22%5D%0A%20%20IDI%20--%3E%20BS%0A%20%20BS%20--%3E%20REV%5B%22%E5%8E%8B%E5%8A%9B%E9%87%8D%E6%A3%80%EF%BC%9A%E7%9B%B8%E5%85%B3%E8%B6%8B%E4%B8%80%E6%97%B6%E5%88%86%E6%95%A3%E5%A4%B1%E6%95%88%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[B("分散的算术在哪里生效：若违约相互独立，损失分布的标准差随名字数按开方收缩，几十个名字就能把个券跳跃压成背景噪音；一旦相关上升，收缩因子失效——危机时违约相关趋于 1，可分散部分向不可分散部分坍缩。CreditMetrics 一族的模型把这个结构写成迁移矩阵加相关结构：组合的尾部由「共同因子打头、个券兑现殿后」的路径生成，所以尾部的边际贡献集中于高相关块，权重小不等于贡献小。这与 "),a("a",{href:"/quant/rc-case-map"},"2020 年案例"),B(" 的判据同源：相关是压力里的状态变量，不是样本内的常数。机制的另一半是代价：粒度要花钱，冷门券的价差与搜索成本随分散度上升——"),a("a",{href:"/quant/bond-liquidity-trace"},"债券流动性账"),B(" 里那本账单在信用层最厚。")],-1)),(t(),r(s,null,{default:e(()=>[n(i,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20LR%0A%20%20IND%5B%22%E8%BF%9D%E7%BA%A6%E7%9B%B8%E4%BA%92%E7%8B%AC%E7%AB%8B%22%5D%20--%3E%20SQ%5B%22%E6%8D%9F%E5%A4%B1%E6%A0%87%E5%87%86%E5%B7%AE%E6%8C%89%E6%A0%B9%E5%8F%B7N%E6%94%B6%E7%BC%A9%22%5D%0A%20%20SQ%20--%3E%20BG%5B%22%E4%B8%AA%E5%88%B8%E8%B7%B3%E8%B7%83%E6%91%8A%E6%88%90%E8%83%8C%E6%99%AF%E5%99%AA%E9%9F%B3%22%5D%0A%20%20COR%5B%22%E8%BF%9D%E7%BA%A6%E7%9B%B8%E5%85%B3%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20FAIL%5B%22%E5%BC%80%E6%96%B9%E6%94%B6%E7%BC%A9%E5%9B%A0%E5%AD%90%E5%A4%B1%E6%95%88%22%5D%0A%20%20FAIL%20--%3E%20CL%5B%22%E5%8F%AF%E5%88%86%E6%95%A3%E9%83%A8%E5%88%86%E5%9D%8D%E7%BC%A9%E8%BF%9B%E7%B3%BB%E7%BB%9F%E6%80%A7%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20CL%20--%3E%20ST%5B%22%E7%9B%B8%E5%85%B3%E8%B6%8B%E4%B8%80%20%E5%8D%B3%E5%88%86%E6%95%A3%E5%A4%B1%E6%95%88%E6%97%B6%E5%88%BB%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=A('<p><span class="marginnote">数字实例：50 个相互独立的发行人，单名违约损失的波动若为 2%，摊到组合层面约为 \\(2\\%/\\sqrt{50}\\approx 0.28\\%\\)——这就是「开方收缩」；一旦违约相关升到 0.5 以上，实际标准差可能停在 1% 附近，摊薄效果折损大半。</span></p><p><span class="marginnote">前十发行人占 40% 权重、其余 90 个平分 60% 的组合：HHI 约 0.020，有效 N 约 50——名义上 100 个发行人，有效分散只有一半。名字数量从不等于粒度。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>上限约束不等于尾部约束：行业上限各自合规，行业间相关上升时组合照样失守，压力场景必须跨行业设相关。指数对冲只对成分精确，持仓与成分的差是基差，压利差时基差往往先动（见信用与指数基差课）。违约相关本身难以估计，股权代理与利差代理给出的是区间不是点——模型输出的尾部数字要带区间报。评级是滞后指标，迁移风险先于违约出现，只盯违约率的组合会错过一半的坏消息。最后，LGD 有自己的分布与周期，回收率在系统性压力下系统性走低，分散的算术里它是另一个被低估的输入。</p><p><span class="marginnote">常见误区：把评级当成及时的风险排序。实际上评级下调常发生在利差已经走阔、股价已经下跌之后——等评级动了再减仓，等于用最贵的价格卖。「迁移风险」（评级往坏走的概率）比违约本身来得早得多。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>信用分散的分工：可分散的个券跳跃用权重摊薄，系统性利差贝塔用指数承载或对冲。</li><li>度量先行：有效 N 按 HHI 计，期望损失与相关无关，非期望损失才是分散的对象。</li><li>相关是状态变量：压力下趋于 1，分散的收益恰在最需要时消失。</li><li>粒度有价：冷门券的价差与搜索成本随分散度上升，预算要写在方案里。</li><li>出处：据 Gupton, Finger and Bhatia, CreditMetrics（1997）与 Fabozzi 相关章节整理；相关与基差的判据见本站信用组合与 CDS 指数相关课。</li></ul>',7))])}const _=o(D,[["render",p]]);export{h as __pageData,_ as default};
